use crate::aap::caps::inference_llm;

struct Node;

const MAX_QUESTION_CHARS: usize = 512;

/// Truncate to at most `max` Unicode scalar values, so `len(question) <= 512`
/// holds regardless of the model's output length.
fn clamp_chars(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        s.chars().take(max).collect()
    }
}

/// Map a free-text label from the model onto the closed intent set. The enum has
/// no "other" case, so anything unrecognised collapses to `unknown`; this is how
/// the `ensures intent in [...]` postcondition is made true by construction
/// rather than by a runtime check that could be widened.
fn parse_intent(label: &str) -> Intent {
    match label.trim().to_ascii_lowercase().as_str() {
        "billing_question" | "billing-question" => Intent::BillingQuestion,
        "technical_support" | "technical-support" => Intent::TechnicalSupport,
        "account_change" | "account-change" => Intent::AccountChange,
        "general_inquiry" | "general-inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // Precondition the graph guarantees: len(value.text) <= 4000. We do not
        // re-send or persist the untrusted text anywhere; it is used only as
        // material for the one model call this node is permitted.
        let system = "You classify a customer support message into exactly one \
            intent. Valid intents are: billing_question, technical_support, \
            account_change, general_inquiry, unknown. Respond with only the \
            single intent label and nothing else.";

        let label = inference_llm::infer(system, &message.text, "classify");
        let intent = parse_intent(&label);

        // `question` is the bounded free-text residual that rides along with the
        // discharged query. Clamp it so the postcondition len(question) <= 512
        // holds for any input.
        let question = clamp_chars(message.text.trim(), MAX_QUESTION_CHARS);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
